( -16 -16 -176 ) ( 2832 -16 -160 ) ( 2832 -16 -176 ) 50-free-textures/concrete_pavement_036 0 0 0 1 1
( -16 -16 -176 ) ( 2832 2832 -176 ) ( -16 2832 -176 ) 50-free-textures/concrete_pavement_036 0 0 0 1 1
